        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "Network of carbonized Osteocyte lacuna linked together in the bone (mineral) matrix.  The caliculi are well preserved and can be traced to adjacent osteocytes.  It is unknown if the carbon is the product of cell distillation or migration from the coal shale.  This thin-section is composed of the Remnants of both fish bone and denticles.",
        "figure": "",
