        "description": "Network of nearly perfectly preserved osteocytes in a longitudinal section of spongy bone (Aspidin), this represents part of a fish fossil that was found in Carboniferous coal shale (Northumberland, UK).  Each lacuna holds the condensed and calcified remnant of what appears to be the original cell, (lacuna are small chambers in the mineralized bone that hold the Osteocytes).  A uniform net of osteocytes are connected by a web of preserved dendroid caliculi. The clean and smooth walls of the caliculi indifferential interference contrastate almost no degradation. Fossil bone samples found in Northumberland Carboniferous coal shales are considered to be 350 million years old (myo). ",
        "figure": "",
