        "location": "Gloucestershire",
        "country": "UK",
        "description": "This fish tooth is just one of many fossil Remnants found in a sample from the Aust Cliff, Bone Bed, UK, also known as the Rhaetic Bone Bed.  Aust Cliff is located in Gloucestershire, near Avon, situated on the southern side of the Severn River Estuary.  This is one of the most famous exposures of Triassic rocks in the world.  The image shows a complete cross-section of the tooth including a large pulp cavity at the base. Within the dentine can be seen a dense pattern of tubules extending from the Pulp cavity. The outer surface is covered with an emel crown.  The tooth was deposited in granular siliceous sediment.",
        "figure": "",
