        "site": "bone bed",
        "location": "Gloucestershire",
        "country": "UK",
        "description": "This is a longitudinal section beginning with the tip and ending with a fractured termition.  Within the dentin can be seen converging fibers that actually represent thin dentil tubules.  Ultimately, the tubules originate from a central pulp cavity.  The outer surface of the tooth is covered with an emel crown.  Under crossed polarized light the emel looks brighter due to a higher birefringence, presenting as purple in some areas.  This tooth is just one of many fossils found in this sample from the Aust Cliff, Bone Bed, UK, also known as the Rhaetic Bone Bed.  Aust Cliff is located in Gloucestershire, near Avon, situated on the southern side of the Severn River Estuary.  This is one of the most well known Triassic formations in the world.",
