        "site": "bone bed",
        "location": "Gloucestershire",
        "country": "UK",
        "description": "This is a longitudinal section illustrating the central body of the tooth.  Throughout the dentin can be seen converging fibers that actually represent thin dentil tubules.  This network of tubules originated from the central pulp cavity.  They are formed by Odontoblasts during the growth phase.  Odontoblasts line the endostial walls of the pulp cavity secreting dentine through tubules as the tooth thickens.  This tooth is just one of many fossils found in this sample from the Aust Cliff, Bone Bed, UK, also known as the Rhaetic Bone Bed.  Aust Cliff is located in Gloucestershire, near Avon, situated on the southern side of the Severn River Estuary.  This is one of the most well known Triassic formations in the world.  The tooth is deposited within granular siliceous sediment.",
        "figure": "",
