        "description": "This image illustrates a number of Osteocytes having unusually large and well defined caliculi.  These cells were found in an unidentified fish scale.  The scale (denticle) was isolated from within a coprolite that was deposited in coal shale (Carboniferous coal shale, Northumberland, UK).  Inside the lacuna can be seen the siliceous Remnants of the cell cytoplasm. Inside the opening of the lacuna (bottom side) can be seen the progression of the cells filipodia into the caliculi (submicron sized tubes connecting osteocytes within the mineral matrix).  Scattered throughout the dentine can be seen unraveled collagen fibers. The fibers have been darkened with a tural ferrous oxide stain.",
