        "location": "Northumberland",
        "country": "UK",
        "description": "Suspended in the cavity of a fish dermal tubercle can be seen what look like cells that have retained their membranes.  Typically, the most abundant cell in this type of cavity is a fibroblast (responsible for formation of collagen).  Lower center can be seen a very elongated cell with what appears to be a granulated nucleus.  Under polarized light there is almost no birefringence within the individual cells implying little mineralization.  However, the cavity has been permineralized by a transparent dissolved silicate.  The bright red colors are produced by the insertion of a 1st order red compensator.  In this specimen much of the dermal skeleton is composed of odontogenic tissues (dentin).  The sample is from Carboniferous coal shale, Northumberland, UK.",
        "figure": "",
        "publication_year": "",
        "first_author": "",
