        "description": "The classic cub shaped iron disulfide (pyrite) nestled in a shallow cavity in this fish bone. This is the result of iron exposed to sulfur eventually creating iron disulfide or pyrite.  This is a common process in fossil diagenesis when sediments contain sulfur.  This sample is from Carboniferous coal shale, Northumberland, UK.",
