        "location": "Northumberland",
        "country": "UK",
        "description": "This is a cross section cut through a patch of fish dermal skeleton.  The tops of each tubercle have been removed leaving a clean view of the interl cavity.  The exterl surface of each tubercle has been stained by migrating carbon from the surrounding coal deposit.  The gold colored zone around the interl margin of each tubercle is mostly dentine while the lighter colored cavity was permineralized with a transparent dissolved silicate.  At this magnification one can see debris suspended within the cavity.  The tubercle itself was deposited by odontogenic tissues (dentin) leaving ripples in the margil walls.  This sample is from Carboniferous coal shale, Northumberland, UK.  ",
