        "description": "Thin section through a fish scale representing Laminated mineral layers.  Each mineral layer features elongated lacuna that generally run parallel with each other.  In this image two lacuna remain connected and contain the decade Remnants of the osteocyte.  Bubbles of gas can be seen as Inclusions trapped inside the lacuna. Caliculi with small inclusions can be seen radiating vertically from an elongated lacuna. This specimen is from Carboniferous coal shale recovered from the Foxyards Colliery, Dudley, UK (1876).",
