        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "High magnification of bone tissue with two fossil cells inside their lacuna. The cells are well mineralized but the one on the right still has a distinct gas inclusion. Early decay produces CO2 and methane and if you are lucky this evidence can still be found in the cell. Throughout the bone matrix can be seen tiny perforations which are cross-sections of tubules of caliculi. The condensed material inside each lacuna is isotropic indicating low mineral content. The sample is from the Carboniferous low main coal shale, Northumberland, UK.",
