        "country": "UK",
        "description": "High magnification of bone tissue with one fossil osteocyte inside its lacuna. The cell looks to be mineralized but still has a distinct gas inclusion. Early decay produces CO2 and methane and if you are lucky this evidence can still be found in the cell. Throughout the bone matrix you can see tiny perforations which are cross-sections of tubules of caliculi. The three-dimensiol material inside the lacuna is isotropic indicating low mineral content. The sample is from the Carboniferous low main coal shale, Northumberland, UK.",
