        "site": "bone bed",
        "location": "Avon",
        "country": "UK",
        "description": "This fish scale is just one of many fossil Remnants found in a sample from the Aust Cliff, Bone Bed, UK, also known as the Rhaetic Bone Bed. Aust Cliff is located within Gloucestershire, near Avon, situated on the southern side of the Severn River Estuary. This is one of the most famous exposures of Triassic rocks in the world. To the right side of this image one well preserved osteocyte can be seen in cross-section within the mineral matrix. What appears to be a nucleus can be seen inside the body of the cell. Extending out from the cell body can be seen unusually thick caliculi.  The cell is slightly differentiated by a tural ferrous oxide stain.",
        "figure": "",
        "publication_year": "",
        "first_author": "",
        "reference": "Unpublished"
