        "description": "This fish tooth is just one of many fossil Remnants found in a sample from the Aust Cliff, Bone Bed, UK, also known as the Rhaetic Bone Bed. Aust Cliff is located within Gloucestershire, near Avon, situated on the southern side of the Severn River Estuary. This is one of the most famous exposures of Triassic rocks in the world. The tooth shows signs of wear such as tumbling on marine bottom sediments. To the right is a small grain of quartz. The background is composted of fractured limestone matrix.",
