        "description": "This is a cross section cut through a patch of a fish dermal skeleton. The tops of each tubercle have been removed leaving a clear view of the interl structure. The dentin that makes up the body of each tubercle can be seen in a gold-brown color with darker zones twisting through the matrix. Most of this dermal sample is composed of odontogenic tissues (dentin). The exterl surface of each tubercle has been stained by migrating carbon from the surrounding coal deposit.",
