        "description": "This is a cross section cut through a single fish dermal tubercle. The top of the tubercle has been removed leaving a clear view of the interl structure. The dentin that makes up the body of can be seen in a gold-brown color with darker zones twisting through the matrix. Most of this dermal sample is composed of odontogenic tissues (dentin). This is a highly magnified image of the inside cavity of the tubercle, trapped within the cavity are what appears to be tiny disks interpreted as the remains of clotted fossilized blood cells. The rust color is likely a tural ferrous oxide stain that binds more easily with decayed organics.",
