        "description": "This is a cross section cut through a circular tubercle that is part of the fish dermal skeleton. The tops of each tubercle have been removed leaving a clear view of the interl structure. The dentin that makes up the body of each tubercle can be seen in a gold-brown color with darker zones twisting through the matrix. Most of this dermal sample is composed of odontogenic tissues (dentin). In the center of the primary tubercle can be seen evidence of the histology inside the cavity. The pulp cavity itself cannot be seen in this microphotograph.",
