        "description": "This is a cross section cut through a patch of fish dermal skeleton. The tops of each tubercle have been removed leaving a clear view of the interl structure. The dentin that makes up the body of each tubercle can be seen in a gold-brown color with darker zones twisting through the matrix. Organic materials are normally stained a darker brown when seen against the light color of the dentin. The circular cell shapes may be an interaction with banded-agate mineral formation; however, most of the sample is composed of odontogenic tissues (dentin).",
