        "country": "UK",
        "description": "This is a longitudinal section of a fish tooth at the intersection of alveolar bone (left) and tooth (right). The black strands in the tooth are dentin tubules which now are carbonized. To the left the white margin is the tooth emel. Separated from the emel to the left is a small section of alveolar bone. Inside the bone tissue can be seen osteocytes and a network of caliculi.",
