        "country": "UK",
        "description": "This is a longitudinal section of alveolar bone with well preserved osteocytes still linked together by surviving caliculi. The tooth itself is out of view and off to the right. The cells are turally stained by migrating carbon from the surrounding coal deposit. Careful inspection of the cells reveals what look like small fatty acid spheres condensed into concretions.",
