        "site": "coal shale",
        "location": "",
        "country": "UK",
        "description": "This specimen is from coal shale with a fossil embedded fish scale (denticle). This is a highly magnified lacuna with the condensed remains of a carbonized osteocyte. Polarized light shows no birefringence within the lacuna. The central area of the lacuna is differentiated by a darker uptake of carbon from the surrounding coal shale deposit. There are tiny concretions throughout along with surviving caliculi extending from the margins of the lacuna.",
        "figure": "",
