        "description": "This section of coal contains a small zone of densely packed bone fragments that look like a part of a coprolite. The sample has both bone and fish scales packed tightly together. The black osteocyte lacuna with their well preserved caliculi, are likely the result of migrating coal particles from the surrounding coal deposits. The source is from the Carboniferous low main coal shale, Northumberland, UK.",
