        "site": "coal shale",
        "location": "",
        "country": "",
        "description": "Transverse section of a coprolite found in Carbonaceous coal deposits. The content of the coprolite is domited by fish bone fragments. Throughout the sample a high density of isometric pyrite framboids (iron disulfide) can be seen. The sample source was from an English coal deposit with more than average sulfur content.",
