        "country": "UK",
        "description": "This specimen is from Carboniferous coal shale that holds the remains of a fossil fish scale (denticle). There are two highly magnified lacuna with the condensed remains of fossilized osteocytes. The interl chamber of the two lacuna contain a lightly colored mineralized cell with a number of dark gas inclusions. The inclusions are now stained a dark color due to the migration of carbon particles. Polarized light shows little birefringence within the lacuna. There continues to be a pretty good network of degraded caliculi that remain in contact with the neighboring cell. The sample was found in Carboniferous English coal shale.",
