        "country": "UK",
        "description": "This specimen is from Carboniferous coal shale that holds the remains of a fossil fish scale (denticle). There are two highly magnified lacuna containing the condensed remains of fossilized osteocytes. The cell chamber on the right contains a lightly colored mineralized granular compound with a number of dark gas inclusions. The inclusions are now stained a dark color due to the migration of carbon particles. Polarized light shows little birefringence within the lacuna. The caliculi are now almost completely degraded and are no longer visible. The sample was found in Carboniferous English coal shale.",
        "figure": "",
