        "description": "This specimen is from Carboniferous coal shale that held the remains of a fossil fish spine.  This image represents a cross-section through the anterior surface of the spine illustrating the micro-ribs or striations. The separated elements along the top are sections through the variations in the structure. The linear cross-hatch patter in the lower half of the sample is a Laminated deposition pattern. The sample was found in Carboniferous English coal shale.",
