        "description": "This fossil fish spine was found in Carboniferous coal shale and is a cross-section through the anterior surface of the spine illustrating the micro-ribs or striations. The separated elements along the top are sections through the variations in the structure. The textural change to the lower right is a transition from primarily bony to a higher collagen composition with an increase in osteocytes. The sample was found in Carboniferous English coal shale.",
