        "country": "UK",
        "description": "This specimen is from Carboniferous coal shale that held the remains of a fossil fish spine. This image represents a cross-section through the anterior surface of the spine illustrating the micro-ribs or striations (right). The separated elements off to the right are sections through the variations in the structure. The linear cross-hatch patter throughout the left side of the sample is Laminated deposition patterns. It can be seen that the lamitions in one layer are about 90 degrees off the lamitions of the next layer. Most fish spines consist of nanocrystalline hydroxyapatite and collagen. The sample was found in Carboniferous English coal shale.",
        "figure": "",
