        "lithology": "",
        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "This is a highly magnified image of a longitudinal section of a fish spine showing a single isolated osteocyte, one of only a few found in this specimen. The most notable feature is the dark zone in the center of the cell. Extending from the margins is a dense network of well preserved caliculi. They can be traced almost across the entire image, which is rare for specimens of this age. Normal lacuna that once held osteocytes are extremely rare throughout the rest of this sample but this should be expected of the histology of a fish dermal spine. Also see No.144, for an enhanced image. This sample is from Carboniferous coal shale, Northumberland, UK.",
        "figure": "",
