        "country": "UK",
        "description": "This is a section through North English coal shale containing scattered Remnants of Rhizodontida, a Carboniferous class of fish, The Rhizodonts are among the Sareopterygians and thrived during the Devonian and Carboniferous, (order; Rhizodontiformes) (family; Rhizodontidae). The specific species is unknown but thought to be Rhizodus hibberti (1864). The fossil fragments consist of fish spines, scales, tusk and dermal skeletal tissues. A characteristic feature is that Rhizodonta have deeply rooted teeth and are rarely found articulated. In this small fragment are exceptiolly preserved osteocytes, with clean caliculi still connected to surrounding companion cells. Inside the lacuna can be seen the process of decay in the early stage of protein separation. As peptides eventually brake down, the lighter fatty acids become separate from the darker nucleic acids. The surrounding and unbroken dense apatite continues to seal off and shielded the osteocytes from bacteria, H20, and oxygen. The coal shale also provides historically low oxygen content. However, Carboniferous cells should not have by any means survived the heat and radiation of this kind of extended geological time. The source of this sample is from the Carboniferous low main coal shale, Northumberland, UK. Fossils of the Rhizodontida have also been found in other U.K. locations including; Foulden, Berwickshire, Scotland and Ballagan Formation, Scotland.",
