        "description": "This is a section through North English coal shale containing scattered Remnants of Rhizodontida, a Carboniferous class of fish, The Rhizodonts are among the Sareopterygians and thrived during the Devonian and Carboniferous, (order; Rhizodontiformes) (family; Rhizodontidae). The specific species is unknown but thought to be Rhizodus hibberti (1864). The fossil fragments consist of fish spines, scales, tusk and dermal skeletal tissues. In this small fragment are found exceptiolly preserved osteocytes, with clean caliculi still connected to surrounding companion cells. Inside the lacuna can be seen traces of the original cell with Remnants of what appears to be nuclei. These cells or part of the remains of a fish spine and were found in the central part of the main spine shaft. The source of this sample is from the Carboniferous low main coal shale, Northumberland, UK. Fossils of the Rhizodontida have also been found in other U.K. locations including; Foulden, Berwickshire, Scotland and Ballagan Formation, Scotland. ",
