        "description": "This is a section through North English coal shale containing scattered Remnants of Rhizodontida, a Carboniferous class of fish, (order; Rhizodontiformes) (family; Rhizodontidae). The specific species is unknown but thought to be Rhizodus hibberti (1864). In this section of shale the fragments consist of fish spines, scales, tusk and dermal skeletal tissues. Under the microscope we see exceptiolly preserved osteocytes, with clean caliculi still connected to surrounding companion cells. This image illustrates a dense network of exceptiolly preserved caliculi, enhanced by the use of DIC. Inside each lacuna the progress of decay can be seen in the early stage of protein separation. As peptides brake down, the lighter fatty acids become separate from the darker nucleic acids. Preservation is aided by the coal shale that provides historically low oxygen content. However, Carboniferous cells should not have by any means survived the heat and radiation of this kind of extended geological time. The source of this sample is from the Carboniferous low main coal shale, Northumberland, UK. Fossils of the Rhizodontida have also been found in other U.K. locations including; Foulden, Berwickshire, Scotland and the Ballagan Formation, Scotland. For high mag. see No.171.",
