        "description": "This is a section through North English coal shale containing the fossil remains of Rhizodontida, a Carboniferous class of fish; The Rhizodonts are among the Sareopterygians and thrived during the Devonian and Carboniferous. The specific species is unknown but thought to be Rhizodus hibberti (1864). These fossil fragments consist of fish spines, scales, tusk and dermal skeletal tissues. In this spine fragment are found well preserved osteocytes, with well defined caliculi. Inside the lacuna can be seen traces of the original content with Remnants of what appears to be organic inclusions. The content of the cells do not produce any detectable birefringence, establishing doubt that significant permineralization has occurred. This image illustrates part of the central shaft of the fossil fish spine. The source of this sample is from the Carboniferous low main coal shale, Northumberland, UK.",
