        "lithology": "",
        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "This ground section of Carboniferous coal was found to contain fragments of fossilized fish. The fragments include teeth, spine and dermal skeletal tissues. This image illustrates the dorsal direction of a small tooth (shows the tip of the tooth) and captures its overall morphology. You may notice that down the center can be seen a lone pulp cavity that is surrounded by mature dentin which still shows the tubules. The high birefringence of the dentine reveals the presents of relatively ultered apatite. On the anterior edge of the tip can still be seen a small amount of emel. Two bisecting fractures have divided the tooth into three separate sections. This polarized light image should be compared with the same view using simple bright-field light (see No.184). This sample is from Carboniferous coal shale, Northumberland, UK.",
