        "interval": "Carboniferous",
        "conventional_age": "",
        "lithology": "",
        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "This ground section of Carboniferous coal was found to contain fragments of fossilized fish. The fragments include teeth, spine and dermal skeletal tissues. This image illustrates the two dorsal ends of a set of fossil fish teeth. This is more of a sagittal cut revealing only short portions of the central pulp cavity. However, you can still see well preserved dentin tubules expanding from the central cavity. The high birefringence of the dentine reveals the presents of relatively ultered apatite. This is a polarized light image with the addition of a first order-red compensator. This sample is from Carboniferous coal shale, Northumberland, UK.",
