        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "This ground section of Carboniferous coal was found to contain fragments of fossilized fish. The fragments include teeth, spine and dermal skeletal tissues. This image illustrates two distinctive teeth and reveals a short portion of the central pulp cavity. Happily, you can still see well preserved dentin tubules radiating from the central cavities. The high birefringence of the dentine reveals the presents of relatively ultered apatite. There is a small fracture that bifurcates the slightly larger bottom tooth. This is a polarized light image with the addition of a 1st order-red compensator. The sample is from Carboniferous coal shale, Northumberland, UK.",
