        "lithology": "",
        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "This ground section of Carboniferous coal was found to contain fragments of fossilized fish. The fragments include teeth, spine and dermal skeletal tissues. At higher magnification this image focuses in on the central pulp cavity. The two different colors seen within the cavity is referred to as pleochroism and is the result of polarized light and the insertion of a 1st order red compensator.  You can also see nicely preserved dentin tubules radiating from the central cavity. The high birefringence of the dentine reveals the presents of relatively ultered apatite. There is a noteworthy fracture that bifurcates the tooth in vertical cross section. This is a polarized light image with the addition of a first order-red compensator. The sample is from Carboniferous coal shale, Northumberland, UK.",
        "figure": "",
