        "description": "This is a cross section cut through a patch of a fish dermal skeleton. The tops of each tubercle have been removed leaving a clean view of the interl composition. Most of a dermal skeleton is composed of odontogenic tissues and in this case a cosmine like dentin which makes up the interl structure of the tubercles. Here we use crossed polarized light and a 1st order red compensator which are now producing interference colors. By rotating the sample we can determine that the tubercles exhibit pleochroism. In this case the red shades may orient in one direction while the yellow-green in the other. If rotated 80 to 90 degrees the colors with switch illustrating the characteristic of pleochroism. This reaction can also be used to identify Remnants of collagen in other fossil and extant tissues. This sample is from Carboniferous coal shale, Northumberland, UK. See No.197 for bright-field image.",
