        "site": "NA",
        "location": "NA",
        "country": "NA",
        "description": "This is a good example of permineralization illustrating calcite deposits within the longitudinal canals of a section of fibrolamellar fossil bone. Calcite normally exhibites first-order color, (grays and glass like) but here we use crossed polarized light, introducing interference colors.",
