        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "Isolated in fossil bone tissue can be seen one stained osteocyte that has retained much of its network of canaliculi. Inside the lacuna you can see the condensed and isolated remains of fatty acids (Adipocerous, sometime referred to as grave wax), and not to be confused with a cell nucleus. The inside walls of the lacuna have been darkened with a natural ferrous oxide stain; this oxidation extends to the walls inside the canaliculi. The content inside of the lacuna appears to be isotropic indicating low mineral content.",
        "figure": "",
