        "description": "Bone tissue with a dense population of osteocytes that remain in an exceptional state of preservation, most of the cells are mineralized but have not all fossilized in quite the same way. Diagenesis has resulted in the incrustation of many of the osteocytes leaving a cottage cheese texture seen within individual lacuna. In all cases the fossil lacuna are isotropic indicating low overall mineral saturation. To the right several lacuna are stained by a natural ferrous oxide deposit. Throughout the bone matrix one can see tiny perforations which are small tubules or canaliculi.",
