        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "Bone tissue with a dense population of osteocytes that remain in an exceptional state of preservation, most of the cells are mineralized but have not all fossilized in quite the same way. Inside the lacuna you can see the condensed and isolated remains of what was at one time fatty acids (Adipocerous, sometime referred to as grave wax). On the left side of the image can be a permineralized canal passing through the depth of the section. In all cases the fossil lacuna are isotropic indicating low overall mineral saturation. Throughout the image some of the lacuna are stained by a natural ferrous oxide deposit. Throughout the bone matrix one can see tiny perforations which are small tubules or canaliculi.",
