        "country": "UK",
        "description": "This is a section through fossil bone having a dense population of osteocytes that remain in a good state of preservation. Most of these cells have been altered over time but have not all fossilized in quite the same way. Inside the lacuna you can see the condensed remains of what were at one time fatty acids (Adipocerous, sometime referred to as grave wax). In most cases the content of the lacuna is isotropic indicating low overall mineral saturation. Also, in this field many of the lacuna are stained by a natural ferrous oxide deposit. Throughout the bone matrix one can see tiny perforations which are small tubules or canaliculi. Finally, there is a thin processing fracture across the top left corner.",
