        "lithology": "",
        "site": "coal shale",
        "location": "Wharncliff",
        "country": "UK",
        "description": "The main maceral in the exinite group is sporinite; this term is used to designate the skins of spores and pollens found in both lignite and bituminous coals (two of the important ranks of coals). In Paleozoic coal, sporinite often occurs in large quantities and remains one of the main constituents of exinite.  In the image these collapsed megaspores are seen perpendicular to the stratification, they are no longer spherical but flattened and compressed due to coalification.",
        "figure": "",
        "publication_year": "",
