        "location": "Grassmoor",
        "country": "UK",
        "description": "Our specific example would likely be better considered a spore-clarite which can be seen alongside other macerals. Diagonally towards the center of the image can be seen what appears to be a sporangium with lightly colored and compacted spores (tetrads). The outer margins of the sporangium are enclosed with a black band which is referred to as exsudatinite. The individual spores or tetrads are considerably more anisotropic than the surrounding macerals. This hints at the presents of surviving cellulose. At the magnification of 550x the individual spores can be clearly differentiated.",
        "figure": "",
