        "description": "Here we have an individual Osteocyte found in the matrix if a fossil fish scale. This cell still has a rather complete network of preserved canaliculi.  Inside the lacuna are the remains of a fossilized osteocyte now condensed and preserved in a very undulate pattern. The inside walls of the lacuna have been stained with a naturally accruing ferrous oxide deposit. This cell likely consists of a waxy concretion made of fossilized fatty acids now forming a smooth surface texture. You should reasonably expect to find that any lacuna from the Carboniferous would be empty or maybe permineralized with a dissolved mineral, but here we find little if no anisotropic compounds, meaning that the cell is altered but not mineralized. The lightly stained and good condition of the canaliculi suggests a state very high preservation.",
