        "description": "These are well preserved Osteocytes with a healthy network of surviving canaliculi.  The endostial walls of the lacuna and canaliculi are lightly colored with a naturally occurring ferrous oxide stain. The dark circular inclusions were formed by the production of gas bubbles in the early stages of decay. Inside each lacuna is a light brown cell consisting of what are likely condensed and fossilized fatty acids. These cells show very little birefringence and don't react to polarized light. The lightly altered and pristine condition of the canaliculi suggests a state of remarkable preservation.",
