        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "This is a well preserved Osteocyte with a healthy network of surviving canaliculi.  The remains of the cell nearly fill the entire lacuna with a little space along the top and bottom margin. There is one large and vary dark gas inclusion found to the lower right, this is likely the result of gases produced during early decay. The texture of the rest of the cell is rather smooth with the exception of a number of small darkened pits. The content of the cell itself appears to be a waxy concretion made of fossilized fatty acids now forming a smooth surface texture. At a number of exit points the old cytoplasm can be seen entering the canaliculi.  . Permineralization appears to be minimal as polarized light reveals very little birefringence. The lightly altered and pristine condition of the canaliculi suggests a state of remarkable preservation.",
        "figure": "",
