        "country": "UK",
        "description": "These are well preserved Osteocytes with a healthy network of surviving canaliculi.  The endostial walls of the lacuna and canaliculi are lightly colored with a naturally occurring ferrous oxide stain. The lacuna hold what appears to be light brown cells that are probably made of fatty acids that by now have condensed to a waxy concretion. These cells show very little birefringence and do not react to polarized light. The large dark cavities seen on the margins of the image are congested vascular canals. The lightly altered and pristine condition of the canaliculi suggests a state of remarkable preservation.",
        "figure": "",
