        "description": "These are well preserved Osteocytes with a healthy network of surviving canaliculi.  The endostial walls of the lacuna and canaliculi are lightly colored with a naturally occurring ferrous oxide stain. A number of very dark circular inclusions were formed by the production of gas bubbles in the early stages of decay. The most interesting feature is what appears as a light colored cell body, likely made of old fossilized fatty acids (adipocere, or grave-wax). It can be seen in the larger cell as a lone and smooth textured cord. The lightly altered condition of the canaliculi suggests a state of good preservation.",
