        "lithology": "",
        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "Thin section through a zone of the fish scale where laminated mineral layers dominate. Within each layer and along minute fishers can be seen individual lacuna that generally runs parallel with each other. Here we see a single lacuna that appears to retain the decade remnants of the osteocyte. Stained organics can be seen extending from the cell along geometrical fishers found in the mineral matrix (scale). These liner canaliculi have small inclusions or congestion that over time has picked up a natural ferrous oxide stain.",
        "figure": "",
