        "site": "coal shale",
        "location": "Northumberland",
        "country": "UK",
        "description": "This is a good example of what one would expect to see in fossilized Carboniferous bone cells. The lacuna and canaliculi are still defined but the osteocytes themselves have been reduced to fragments of carbon. In this case the carbon is either the product of heat and pressure without oxygen or the migration of carbon from the surrounding coal shale. This path of taphonomy is not unique as other cells in this same sample have distilled in this same pattern (See No.268). Here we find there has been significant alteration and bubbles have formed in the concretions that now occupy the lacuna. As you would expect, there is no preservation of the original osteocytes (cells).",
        "figure": "",
        "publication_year": "",
