        "location": "Northumberland",
        "country": "UK",
        "description": "This is a good example of what one would expect to see in an isolated Carboniferous bone cell. The lacuna and canaliculi are still defined but the osteocyte itself has completely decayed leaving only a tiny bit of organics. As you would expect, there is no preservation of the original osteocyte (cell). Empty lacuna should be the norm with perhaps the permineralization by dissolved minerals that would usually light up under polarized light.",
        "figure": "",
